def prime_factors(n):
    """
    Returns a list of prime factors of n in decreasing order.
    """
    factors = []
    # Check for number of 2s in n
    while n % 2 == 0:
        factors.append(2)
        n = n // 2

    # Check for odd factors from 3 onwards
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2

    # If n becomes a prime number greater than 2
    if n > 2:
        factors.append(n)

    return sorted(factors, reverse=True)
